    "title": "LogiTwin — Gêmeo Digital Portuário",
    "sw_nome": "LogiTwin — Gêmeo Digital Portuário",
    "pf_nome": "Equipe LogiTwin",
    "Nome_fantasia": "LogiTwin Soluções Portuárias",
